"""Actual P1 affine rigid-null step constrained by ALL original finite gaps.
A numerical linear seed only, not support state substitution or equilibrium.
"""
import sys,json,time,shutil
import numpy as np
from scipy import sparse
from scipy.optimize import linprog
from baseline_registry import ROOT,REPO,ref,dump

def main():
 t=time.monotonic();assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'producer.py');ns=ROOT/'validation/integrated/primaryP1_physical_null_work1/summary.json';s=json.loads(ns.read_text());source=json.loads((REPO/s['source']['path']).read_text());P=sparse.load_npz(REPO/s['physical_P']['path']);A=sparse.load_npz(REPO/s['physical_A']['path']);p=np.load(REPO/s['problem']['path']);x=np.load(REPO/source['output']['path'])['after_x'];n=np.load(REPO/s['output']['path']);V=n['R']@n['Z'];V/=np.maximum(np.max(abs(V),axis=0),1e-30);B=np.asarray(A@V);force=P@x+p['q'];f=V.T@force;sl=A@x-p['lower'];eq=np.isfinite(p['upper'])&(p['lower']==p['upper']);ineq=~eq;r=linprog(f,A_ub=-B[ineq],b_ub=sl[ineq],A_eq=B[eq],b_eq=-sl[eq],bounds=[(None,None)]*V.shape[1],method='highs',options=dict(primal_feasibility_tolerance=1e-10,dual_feasibility_tolerance=1e-10,time_limit=30.));accepted=False;metrics={};output=None
 if r.success:
  dx=V@r.x;gt=float(force@dx);curv=float(dx@(P@dx));alpha=min(1.,-gt/curv) if gt<0 and curv>0 else 1.;trial=x+alpha*dx;end=A@trial-p['lower'];pr=max(float(np.max(np.maximum(-end[ineq],0))),float(np.max(abs(end[eq]))));before=float(.5*x@(P@x)+p['q']@x);after=float(.5*trial@(P@trial)+p['q']@trial);accepted=pr<1e-10 and gt<0 and after<=before+1e-4*alpha*gt;lp_y=np.zeros(len(sl));lp_y[ineq]=r.ineqlin.marginals;lp_y[eq]=-r.eqlin.marginals;lpstat=f+B.T@lp_y;lpc=float(np.max(abs((sl+B@r.x)[ineq]*lp_y[ineq])));new=x+alpha*dx if accepted else x;output=out/'null_step.npz';np.savez_compressed(output,before_x=x,V=V,B=B,coefficients=r.x,full_gap_RHS=sl,objective_f=f,direction=dx,after_x=new,proposed_x=trial,LP_dual=lp_y,LP_stationarity=lpstat,physical_Pv=P@V);metrics=dict(allrow_primal_mm=pr,physical_objective_before_Nmm=before,physical_objective_after_Nmm=after if accepted else before,physical_directional_objective_Nmm=gt,physical_curvature_Nmm=curv,alpha=alpha,max_increment_mm_rad=float(np.max(abs(alpha*dx))),LP_stationarity=float(np.max(abs(lpstat))),LP_sign=float(np.max(np.maximum(lp_y[ineq],0))),LP_complementarity_Nmm=lpc,new_near_original_rows=np.flatnonzero(ineq&(end<=1e-10)&(sl>1e-10)).tolist(),all_near_original_rows=np.flatnonzero(ineq&(end<=1e-10)).tolist())
 result=dict(status='ACTUAL_P1_ALLROW_FINITE_NULL_STEP_ACCEPTED_NOT_EQUILIBRIUM' if accepted else 'ACTUAL_P1_ALLROW_FINITE_NULL_STEP_REJECTED',candidate=s['candidate'],source=ref(ns),physical_source=s['source'],physical_P=s['physical_P'],physical_A=s['physical_A'],problem=s['problem'],producer=ref(out/'producer.py'),output=ref(output) if output else None,LP_status=int(r.status),LP_message=r.message,metrics=metrics,accepted_linear_steps=int(accepted),actual_support_updates=0,accepted_equilibria=0,newly_qualified_system_gate_ids=[],whole_system_release=False,elapsed_s=time.monotonic()-t,limitations=['All original finite gaps/equalities enter a two-coordinate LP numerical direction. Full original P/q objective and all2208row 1e-10mm checks decide acceptance; LP duals are NOT physical pressures.','Null candidate is numerical, with original measured P-action errors retained; physical curvature is evaluated, never assumed zero. No physical spring/row deletion/sourcefield replacement/nonlinear update or release.']);dump(out/'summary.json',result);print(json.dumps(result));raise SystemExit(0 if accepted else 2)
if __name__=='__main__':main()
